GK: ["GK"],
LB: ["LWB", "CB", "RB"],
CB: ["LB", "RB", "6"],
RB: ["RWB", "CB", "LB"],
LWB: ["LB", "LW", "RWB"],
RWB: ["RB", "RW", "LWB"],
6: ["8", "CB", "10"],
8: ["6", "10", "LW", "RW"],
10: ["8", "ST", "LW", "RW"],
LW: ["LWB", "RW", "10", "ST"],
RW: ["RWB", "LW", "10", "ST"],
ST: ["10", "LW", "RW"],
